			bulkCopy.BulkCopyTimeout = 360;
			bulkCopy.DestinationTableName = "Hotel";
			
			DataTable dataTable = new DataTable();
			DataColumn col0 = dataTable.Columns.Add("HotelID", typeof(System.Guid));
			col0.AllowDBNull = false;		
			DataColumn col1 = dataTable.Columns.Add("Nombre", typeof(System.String));
