			bulkCopy.ColumnMappings.Add("GoogleMapHtml", "GoogleMapHtml");
			bulkCopy.ColumnMappings.Add("LocalidadID", "LocalidadID");
			
			foreach(MAT.Entities.Hotel entity in entities)
			{
				if (entity.EntityState != EntityState.Added)
					continue;
					
				DataRow row = dataTable.NewRow();
				
					row["HotelID"] = entity.HotelId;
							
				
					row["Nombre"] = entity.Nombre;
							
				
